// ───────────────────────────── fonts (resolved from YAML carrier labels) ─────────────
struct Fonts {
  const lv_font_t *t13 = nullptr, *t16 = nullptr, *t18 = nullptr, *t20 = nullptr, *t24 = nullptr,
                  *t30 = nullptr, *t48 = nullptr, *i20 = nullptr, *i24 = nullptr, *i28 = nullptr,
                  *i40 = nullptr, *kb = nullptr;
};
inline Fonts F;

// ───────────────────────────── language ─────────────────────────────
inline int *g_lang = nullptr;  // points at the firmware's current_language global
enum Lang { EN = 0, RU = 1, UK = 2 };
inline Lang lang() {
  int l = g_lang ? *g_lang : 7;
  return l == 6 ? RU : (l == 9 ? UK : EN);
}
inline const char *T(const char *en, const char *ru, const char *uk) {
  Lang l = lang();
  return l == RU ? ru : (l == UK ? uk : en);
}

inline std::string U(uint32_t cp) {
  std::string s;
  if (cp < 0x80) s += (char) cp;
  else if (cp < 0x800) { s += (char) (0xC0 | (cp >> 6)); s += (char) (0x80 | (cp & 0x3F)); }
  else if (cp < 0x10000) { s += (char) (0xE0 | (cp >> 12)); s += (char) (0x80 | ((cp >> 6) & 0x3F)); s += (char) (0x80 | (cp & 0x3F)); }
  else { s += (char) (0xF0 | (cp >> 18)); s += (char) (0x80 | ((cp >> 12) & 0x3F)); s += (char) (0x80 | ((cp >> 6) & 0x3F)); s += (char) (0x80 | (cp & 0x3F)); }
  return s;
}

// ───────────────────────────── host bindings ─────────────────────────────
struct Host {
  std::function<void(const std::string &, const std::string &)> call;  // service, json data
  std::function<void(const std::string &)> search;
  std::function<void()> library;
  std::function<void(const std::string &)> set_art;
  std::function<bool()> screensaver;
  std::function<void()> wake;
  std::string ha_url;
  lv_obj_t *home = nullptr, *settings = nullptr, *nav = nullptr;
  std::function<lv_image_dsc_t *()> get_art;
  bool dry_run = false;
};
inline Host H;

// ───────────────────────────── state store ─────────────────────────────
inline std::map<std::string, std::string> S;
inline bool g_dirty = true;
inline std::map<std::string, std::string> HA_S;   // last value confirmed by Home Assistant
inline std::map<std::string, uint32_t> OPT;         // optimistic values awaiting confirmation
// Optimistic update after a user action (keys starting with "rc." are UI-local and never expire).
inline void set_state(const std::string &k, const std::string &v) {
  auto &cur = S[k];
  if (cur != v) { cur = v; g_dirty = true; }
  if (k.rfind("rc.", 0) != 0) OPT[k] = lv_tick_get();
}
// Value pushed by Home Assistant: always wins.
inline void ha_state(const std::string &k, const std::string &v) {
  HA_S[k] = v;
  OPT.erase(k);
  auto &cur = S[k];
  if (cur != v) { cur = v; g_dirty = true; }
}
// If HA did not confirm within 10 s (device offline, command lost), show the real state again.
inline void expire_optimistic() {
  for (auto it = OPT.begin(); it != OPT.end();) {
    if (lv_tick_elaps(it->second) < 10000) { ++it; continue; }
    auto h = HA_S.find(it->first);
    S[it->first] = h == HA_S.end() ? std::string() : h->second;
    g_dirty = true;
    it = OPT.erase(it);
  }
}
inline const std::string &st(const std::string &k) {
  static const std::string empty;
  auto it = S.find(k);
  return it == S.end() ? empty : it->second;
}
inline float stf(const std::string &k, float def = NAN) {
  const auto &v = st(k);
  if (v.empty()) return def;
  char *e = nullptr;
  float f = strtof(v.c_str(), &e);
  return e == v.c_str() ? def : f;
}
inline bool on(const std::string &k) { return st(k) == "on"; }
inline bool avail(const std::string &k) {
  const auto &v = st(k);
  return !v.empty() && v != "unavailable" && v != "unknown" && v != "None";
}
inline bool has(const std::string &k, const char *needle) { return st(k).find(needle) != std::string::npos; }

// ───────────────────────────── JSON + HA calls ─────────────────────────────
inline std::string jesc(const std::string &s) {
  std::string o;
  for (char c : s) {
    if (c == '"' || c == '\\') { o += '\\'; o += c; }
    else if (c == '\n') o += "\\n";
    else o += c;
  }
  return o;
}
struct J {
  std::string s = "{";
  J &k(const char *key, const std::string &v) { sep(); s += "\"" + std::string(key) + "\":\"" + jesc(v) + "\""; return *this; }
  J &n(const char *key, double v) { sep(); char b[32]; snprintf(b, sizeof b, "%g", v); s += "\"" + std::string(key) + "\":" + b; return *this; }
  J &raw(const char *key, const std::string &v) { sep(); s += "\"" + std::string(key) + "\":" + v; return *this; }
  J &b(const char *key, bool v) { return raw(key, v ? "true" : "false"); }
  std::string str() const { return s + "}"; }
 private:
  void sep() { if (s.size() > 1) s += ","; }
};
inline void call(const std::string &svc, const std::string &data) {
  ESP_LOGW("rc", "CALL %s %s", svc.c_str(), data.c_str());
  if (!H.dry_run && H.call) H.call(svc, data);
}
// Runs a HA script in the background with variables (returns immediately).
inline void run_script(const char *entity, const std::string &vars = "{}") {
  call("script.turn_on", J().k("entity_id", entity).raw("variables", vars).str());
}
// Entity id list "a,b,c" -> JSON array.
inline std::string ents(const std::string &csv) {
  std::string o = "[";
  size_t p = 0;
  while (p <= csv.size()) {
    size_t q = csv.find(',', p);
    if (q == std::string::npos) q = csv.size();
    if (o.size() > 1) o += ",";
    o += "\"" + csv.substr(p, q - p) + "\"";
    p = q + 1;
  }
  return o + "]";
}

// ───────────────────────────── events ─────────────────────────────
struct Cb { std::function<void(lv_event_t *)> f; };
inline void cb_run(lv_event_t *e) {
  auto *c = static_cast<Cb *>(lv_event_get_user_data(e));
  if (c && c->f) c->f(e);
}
inline void cb_del(lv_event_t *e) { delete static_cast<Cb *>(lv_event_get_user_data(e)); }
inline void on_ev(lv_obj_t *o, lv_event_code_t code, std::function<void(lv_event_t *)> f) {
  auto *c = new Cb{std::move(f)};
  lv_obj_add_event_cb(o, cb_run, code, c);
  lv_obj_add_event_cb(o, cb_del, LV_EVENT_DELETE, c);
}
inline void on_click(lv_obj_t *o, std::function<void()> f) {
  lv_obj_add_flag(o, LV_OBJ_FLAG_CLICKABLE);
  on_ev(o, LV_EVENT_CLICKED, [f](lv_event_t *) { f(); });
}

// Named widgets, used by the test harness (API action rc_click).
inline std::map<std::string, lv_obj_t *> REG;
inline lv_obj_t *reg(lv_obj_t *o, const std::string &name) {
  REG[name] = o;
  on_ev(o, LV_EVENT_DELETE, [name, o](lv_event_t *) {
    auto it = REG.find(name);
    if (it != REG.end() && it->second == o) REG.erase(it);
  });
  return o;
}
inline bool click(const std::string &name) {
  auto it = REG.find(name);
  if (it == REG.end()) return false;
  lv_obj_send_event(it->second, LV_EVENT_CLICKED, nullptr);
  return true;
}

// ───────────────────────────── styles + micro animations ─────────────────────────────
inline lv_style_t s_anim, s_pressed;
inline lv_style_transition_dsc_t s_tr;
inline void styles_init() {
  static bool done = false;
  if (done) return;
  done = true;
  static const lv_style_prop_t props[] = {LV_STYLE_TRANSFORM_WIDTH, LV_STYLE_TRANSFORM_HEIGHT, LV_STYLE_PROP_INV};
  lv_style_transition_dsc_init(&s_tr, props, lv_anim_path_ease_out, 140, 0, nullptr);
  lv_style_init(&s_anim);
  lv_style_set_transition(&s_anim, &s_tr);
  lv_style_init(&s_pressed);
  lv_style_set_transform_width(&s_pressed, -3);
  lv_style_set_transform_height(&s_pressed, -3);
}
// Tactile press: the surface shrinks 3 px with an eased transition (redraws only the widget).
inline void pressable(lv_obj_t *o) {
  lv_obj_add_style(o, &s_anim, 0);
  lv_obj_add_style(o, &s_pressed, LV_STATE_PRESSED);
  lv_obj_add_flag(o, LV_OBJ_FLAG_CLICKABLE);
}

struct ColAnim { lv_obj_t *o; lv_color_t a, b; bool text; };
inline void anim_color(lv_obj_t *o, uint32_t to, bool text = false, uint32_t ms = 220) {
  lv_color_t from = text ? lv_obj_get_style_text_color(o, LV_PART_MAIN) : lv_obj_get_style_bg_color(o, LV_PART_MAIN);
  if (lv_color_eq(from, col(to))) return;
  auto *d = new ColAnim{o, from, col(to), text};
  lv_anim_t a;
  lv_anim_init(&a);
  lv_anim_set_var(&a, d);
  lv_anim_set_user_data(&a, d);
  lv_anim_set_values(&a, 0, 255);
  lv_anim_set_duration(&a, ms);
  lv_anim_set_path_cb(&a, lv_anim_path_ease_out);
  lv_anim_set_custom_exec_cb(&a, [](lv_anim_t *an, int32_t v) {
    auto *d = static_cast<ColAnim *>(lv_anim_get_user_data(an));
    lv_color_t c = lv_color_mix(d->b, d->a, (uint8_t) v);
    if (d->text) lv_obj_set_style_text_color(d->o, c, 0);
    else lv_obj_set_style_bg_color(d->o, c, 0);
  });
  lv_anim_set_deleted_cb(&a, [](lv_anim_t *an) { delete static_cast<ColAnim *>(lv_anim_get_user_data(an)); });
  lv_anim_start(&a);
}
inline void anim_x(lv_obj_t *o, int to, uint32_t ms = 200) {
  lv_anim_t a;
  lv_anim_init(&a);
  lv_anim_set_var(&a, o);
  lv_anim_set_values(&a, lv_obj_get_x(o), to);
  lv_anim_set_duration(&a, ms);
  lv_anim_set_path_cb(&a, lv_anim_path_ease_out);
  lv_anim_set_exec_cb(&a, [](void *v, int32_t x) { lv_obj_set_x((lv_obj_t *) v, x); });
  lv_anim_start(&a);
}
// Small "bounce" used as feedback when a scene or quick action fires.
inline void pulse(lv_obj_t *o) {
  lv_obj_set_style_transform_pivot_x(o, lv_obj_get_width(o) / 2, 0);
  lv_obj_set_style_transform_pivot_y(o, lv_obj_get_height(o) / 2, 0);
  lv_anim_t a;
  lv_anim_init(&a);
  lv_anim_set_var(&a, o);
  lv_anim_set_values(&a, 256, 300);
  lv_anim_set_duration(&a, 130);
  lv_anim_set_reverse_duration(&a, 170);
  lv_anim_set_path_cb(&a, lv_anim_path_ease_out);
  lv_anim_set_exec_cb(&a, [](void *v, int32_t s) { lv_obj_set_style_transform_scale((lv_obj_t *) v, s, 0); });
  lv_anim_start(&a);
}
// Gentle breathing opacity for "running" indicators (small objects only).
inline void breathe(lv_obj_t *o, bool enable) {
  lv_anim_delete(o, nullptr);
  lv_obj_set_style_opa(o, LV_OPA_COVER, 0);
  if (!enable) return;
  lv_anim_t a;
  lv_anim_init(&a);
  lv_anim_set_var(&a, o);
  lv_anim_set_values(&a, 255, 110);
  lv_anim_set_duration(&a, 900);
  lv_anim_set_reverse_duration(&a, 900);
  lv_anim_set_repeat_count(&a, LV_ANIM_REPEAT_INFINITE);
  lv_anim_set_path_cb(&a, lv_anim_path_ease_in_out);
  lv_anim_set_exec_cb(&a, [](void *v, int32_t x) { lv_obj_set_style_opa((lv_obj_t *) v, (lv_opa_t) x, 0); });
  lv_anim_start(&a);
}

// ───────────────────────────── primitives ─────────────────────────────
inline lv_obj_t *screen() {
  lv_obj_t *s = lv_obj_create(nullptr);
  lv_obj_remove_style_all(s);
  lv_obj_set_style_bg_color(s, col(C_BG), 0);
  lv_obj_set_style_bg_opa(s, LV_OPA_COVER, 0);
  lv_obj_remove_flag(s, LV_OBJ_FLAG_SCROLLABLE);
  return s;
}
inline lv_obj_t *box(lv_obj_t *p, int x, int y, int w, int h, uint32_t bg, int r = 0) {
  lv_obj_t *o = lv_obj_create(p);
  lv_obj_remove_style_all(o);
  lv_obj_set_pos(o, x, y);
  lv_obj_set_size(o, w, h);
  lv_obj_set_style_bg_color(o, col(bg), 0);
  lv_obj_set_style_bg_opa(o, LV_OPA_COVER, 0);
  lv_obj_set_style_radius(o, r, 0);
  lv_obj_remove_flag(o, LV_OBJ_FLAG_SCROLLABLE);
  lv_obj_remove_flag(o, LV_OBJ_FLAG_CLICKABLE);
  return o;
}
inline lv_obj_t *plain(lv_obj_t *p, int x, int y, int w, int h) {
  lv_obj_t *o = box(p, x, y, w, h, 0, 0);
  lv_obj_set_style_bg_opa(o, LV_OPA_TRANSP, 0);
  return o;
}
inline lv_obj_t *text(lv_obj_t *p, const std::string &s, const lv_font_t *f, uint32_t c, int x, int y, int w = 0,
                      lv_text_align_t al = LV_TEXT_ALIGN_LEFT) {
  lv_obj_t *l = lv_label_create(p);
  lv_label_set_text(l, s.c_str());
  lv_obj_set_style_text_font(l, f, 0);
  lv_obj_set_style_text_color(l, col(c), 0);
  lv_obj_set_style_text_align(l, al, 0);
  lv_obj_set_pos(l, x, y);
  if (w > 0) {
    lv_obj_set_width(l, w);
    lv_obj_set_height(l, lv_font_get_line_height(f));  // one line, "…" when too long
    lv_label_set_long_mode(l, LV_LABEL_LONG_MODE_DOTS);
  }
  return l;
}
inline void set_text(lv_obj_t *l, const std::string &s) {
  if (strcmp(lv_label_get_text(l), s.c_str()) != 0) lv_label_set_text(l, s.c_str());
}
inline lv_obj_t *icon(lv_obj_t *p, uint32_t cp, const lv_font_t *f, uint32_t c) {
  lv_obj_t *l = lv_label_create(p);
  lv_label_set_text(l, U(cp).c_str());
  lv_obj_set_style_text_font(l, f, 0);
  lv_obj_set_style_text_color(l, col(c), 0);
  return l;
}
// Round icon badge; the glyph is always centred in the circle.
inline lv_obj_t *chip(lv_obj_t *p, int x, int y, int d, uint32_t cp, const lv_font_t *f, uint32_t fg, uint32_t bg) {
  lv_obj_t *b = box(p, x, y, d, d, bg, LV_RADIUS_CIRCLE);
  lv_obj_t *l = icon(b, cp, f, fg);
  lv_obj_center(l);
  return b;
}
inline lv_obj_t *chip_icon(lv_obj_t *chip) { return lv_obj_get_child(chip, 0); }
inline void set_icon(lv_obj_t *chip, uint32_t cp) { set_text(chip_icon(chip), U(cp)); }

enum Kind { PRIMARY, SECONDARY, GHOST, DANGER, SELECTED, DISABLED };
inline void pill_kind(lv_obj_t *b, Kind k) {
  uint32_t bg = C_SURF2, fg = C_TEXT, border = C_SURF2;
  switch (k) {
    case PRIMARY: bg = C_ACCENT; fg = 0xFFFFFF; border = C_ACCENT; break;
    case SECONDARY: bg = C_SURF2; fg = C_TEXT; border = C_SURF3; break;
    case GHOST: bg = C_SURF; fg = C_TEXT2; border = C_SURF3; break;
    case DANGER: bg = 0x3A1D22; fg = 0xFF8A8F; border = 0x5A2A31; break;
    case SELECTED: bg = C_ACCENT_BG; fg = 0xFFFFFF; border = C_ACCENT; break;
    case DISABLED: bg = C_SURF; fg = C_TEXT3; border = C_SURF2; break;
  }
  anim_color(b, bg);
  lv_obj_set_style_border_color(b, col(border), 0);
  uint32_t n = lv_obj_get_child_count(b);
  for (uint32_t i = 0; i < n; i++) lv_obj_set_style_text_color(lv_obj_get_child(b, i), col(fg), 0);
  if (k == DISABLED) lv_obj_remove_flag(b, LV_OBJ_FLAG_CLICKABLE);
  else lv_obj_add_flag(b, LV_OBJ_FLAG_CLICKABLE);
}
// Rounded button with optional leading icon; content centred with flex.
inline lv_obj_t *pill(lv_obj_t *p, int x, int y, int w, int h, const std::string &txt, Kind k, uint32_t ic = 0,
                      const lv_font_t *f = nullptr) {
  lv_obj_t *b = box(p, x, y, w, h, C_SURF2, h / 2 > 18 ? 18 : h / 2);
  lv_obj_set_style_border_width(b, 1, 0);
  lv_obj_set_flex_flow(b, LV_FLEX_FLOW_ROW);
  lv_obj_set_flex_align(b, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
  lv_obj_set_style_pad_column(b, 6, 0);
  if (ic) icon(b, ic, F.i20, C_TEXT);
  lv_obj_t *l = lv_label_create(b);  // always present so pill_text() can fill it later
  lv_label_set_text(l, txt.c_str());
  lv_obj_set_style_text_font(l, f ? f : F.t16, 0);
  if (txt.empty() && ic) lv_obj_add_flag(l, LV_OBJ_FLAG_HIDDEN);
  pressable(b);
  lv_obj_set_style_bg_color(b, col(C_SURF2), 0);
  pill_kind(b, k);
  return b;
}
inline void pill_text(lv_obj_t *b, const std::string &txt) {
  uint32_t n = lv_obj_get_child_count(b);
  if (n) set_text(lv_obj_get_child(b, n - 1), txt);
}

// Card surface used for tiles and sections.
inline lv_obj_t *card(lv_obj_t *p, int x, int y, int w, int h, bool press = false) {
  lv_obj_t *c = box(p, x, y, w, h, C_SURF, 20);
  if (press) pressable(c);
  return c;
}
inline lv_obj_t *caption(lv_obj_t *p, const std::string &s, int x, int y) { return text(p, s, F.t16, C_TEXT2, x, y); }

// Segmented control with a sliding highlight.
struct Seg {
  lv_obj_t *root, *ind;
  std::vector<lv_obj_t *> labels;
  int sel = 0, item_w = 0;
  std::function<void(int)> cb;
};
inline void seg_select(Seg *s, int i, bool animate = true) {
  if (!s) return;
  if (i < 0 || i >= (int) s->labels.size()) return;
  s->sel = i;
  int x = 3 + i * s->item_w;
  if (animate) anim_x(s->ind, x);
  else lv_obj_set_x(s->ind, x);
  for (int k = 0; k < (int) s->labels.size(); k++)
    lv_obj_set_style_text_color(s->labels[k], col(k == i ? C_TEXT : C_TEXT2), 0);
}
inline Seg *seg(lv_obj_t *p, int x, int y, int w, int h, const std::vector<std::string> &items, int sel,
                std::function<void(int)> cb, const std::string &name = "") {
  auto *s = new Seg();
  s->cb = std::move(cb);
  s->root = box(p, x, y, w, h, C_SURF, h / 2);
  s->item_w = (w - 6) / (int) items.size();
  s->ind = box(s->root, 3, 3, s->item_w, h - 6, C_SURF3, (h - 6) / 2);
  for (int i = 0; i < (int) items.size(); i++) {
    lv_obj_t *hit = plain(s->root, 3 + i * s->item_w, 0, s->item_w, h);
    lv_obj_t *l = text(hit, items[i], F.t16, C_TEXT2, 0, 0);
    lv_obj_center(l);
    s->labels.push_back(l);
    on_click(hit, [s, i]() {
      if (s->sel == i) return;
      seg_select(s, i);
      if (s->cb) s->cb(i);
    });
    if (!name.empty()) reg(hit, name + "." + std::to_string(i));
  }
  on_ev(s->root, LV_EVENT_DELETE, [s](lv_event_t *) { delete s; });
  seg_select(s, sel, false);
  return s;
}

// iOS-like toggle switch (LVGL switch widget is not compiled in).
struct Toggle { lv_obj_t *root, *knob; bool on; std::function<void(bool)> cb; };
inline void toggle_set(Toggle *t, bool v, bool animate = true) {
  t->on = v;
  int x = v ? 26 : 4;
  if (animate) { anim_x(t->knob, x, 180); anim_color(t->root, v ? C_ACCENT : C_SURF3); }
  else { lv_obj_set_x(t->knob, x); lv_obj_set_style_bg_color(t->root, col(v ? C_ACCENT : C_SURF3), 0); }
}
inline Toggle *toggle(lv_obj_t *p, int x, int y, bool v, std::function<void(bool)> cb, const std::string &name = "") {
  auto *t = new Toggle();
  t->cb = std::move(cb);
  t->root = box(p, x, y, 56, 32, C_SURF3, 16);
  t->knob = box(t->root, 4, 4, 24, 24, 0xFFFFFF, 12);
  on_click(t->root, [t]() {
    toggle_set(t, !t->on);
    if (t->cb) t->cb(t->on);
  });
  if (!name.empty()) reg(t->root, name);
  on_ev(t->root, LV_EVENT_DELETE, [t](lv_event_t *) { delete t; });
  toggle_set(t, v, false);
  return t;
}

// Thick "fill" slider (no knob) - drag anywhere on it.
inline lv_obj_t *fill_slider(lv_obj_t *p, int x, int y, int w, int h, int minv, int maxv, int v, uint32_t color) {
  lv_obj_t *s = lv_slider_create(p);
  lv_obj_remove_style_all(s);
  lv_obj_set_pos(s, x, y);
  lv_obj_set_size(s, w, h);
  lv_slider_set_range(s, minv, maxv);
  lv_slider_set_value(s, v, LV_ANIM_OFF);
  lv_obj_set_style_bg_color(s, col(C_SURF2), LV_PART_MAIN);
  lv_obj_set_style_bg_opa(s, LV_OPA_COVER, LV_PART_MAIN);
  lv_obj_set_style_radius(s, h / 2 > 16 ? 16 : h / 2, LV_PART_MAIN);
  lv_obj_set_style_bg_color(s, col(color), LV_PART_INDICATOR);
  lv_obj_set_style_bg_opa(s, LV_OPA_COVER, LV_PART_INDICATOR);
  lv_obj_set_style_radius(s, h / 2 > 16 ? 16 : h / 2, LV_PART_INDICATOR);
  lv_obj_set_style_bg_opa(s, LV_OPA_TRANSP, LV_PART_KNOB);
  lv_obj_add_flag(s, LV_OBJ_FLAG_CLICKABLE);
  lv_obj_set_ext_click_area(s, 8);
  return s;
}
// Slim slider with a round knob (volume).
inline lv_obj_t *slim_slider(lv_obj_t *p, int x, int y, int w, int minv, int maxv, int v) {
  lv_obj_t *s = fill_slider(p, x, y, w, 6, minv, maxv, v, C_TEXT);
  lv_obj_set_style_bg_color(s, col(0xFFFFFF), LV_PART_KNOB);
  lv_obj_set_style_bg_opa(s, LV_OPA_COVER, LV_PART_KNOB);
  lv_obj_set_style_radius(s, LV_RADIUS_CIRCLE, LV_PART_KNOB);
  lv_obj_set_style_pad_all(s, 7, LV_PART_KNOB);
  lv_obj_set_ext_click_area(s, 14);
  return s;
}

// Standard screen header: optional back button, title, and a right-side slot.
inline lv_obj_t *header(lv_obj_t *scr, const std::string &title, std::function<void()> back) {
  int x = 24;
  if (back) {
    lv_obj_t *b = chip(scr, 16, 16, 44, ic::BACK, F.i24, C_TEXT, C_SURF);
    pressable(b);
    on_click(b, back);
    reg(b, "back");
    x = 72;
  }
  return text(scr, title, F.t30, C_TEXT, x, 18, back ? 250 : 300);
}

// Stepper "−  value  +".
struct Stepper { lv_obj_t *root, *val; int v, lo, hi, step; std::string unit; std::function<void(int)> cb; };
inline void stepper_set(Stepper *s, int v) {
  s->v = v < s->lo ? s->lo : (v > s->hi ? s->hi : v);
  set_text(s->val, std::to_string(s->v) + s->unit);
}
inline Stepper *stepper(lv_obj_t *p, int x, int y, int w, int v, int lo, int hi, int step, const std::string &unit,
                        std::function<void(int)> cb, const std::string &name = "") {
  auto *s = new Stepper{nullptr, nullptr, v, lo, hi, step, unit, std::move(cb)};
  s->root = box(p, x, y, w, 48, C_SURF2, 16);
  lv_obj_t *m = chip(s->root, 4, 4, 40, ic::MINUS, F.i20, C_TEXT, C_SURF3);
  lv_obj_t *pl = chip(s->root, w - 44, 4, 40, ic::PLUS, F.i20, C_TEXT, C_SURF3);
  pressable(m);
  pressable(pl);
  s->val = text(s->root, "", F.t20, C_TEXT, 0, 0);
  lv_obj_align(s->val, LV_ALIGN_CENTER, 0, 0);
  on_click(m, [s]() { stepper_set(s, s->v - s->step); if (s->cb) s->cb(s->v); });
  on_click(pl, [s]() { stepper_set(s, s->v + s->step); if (s->cb) s->cb(s->v); });
  if (!name.empty()) { reg(m, name + ".minus"); reg(pl, name + ".plus"); }
  on_ev(s->root, LV_EVENT_DELETE, [s](lv_event_t *) { delete s; });
  stepper_set(s, v);
  return s;
}

// Choice chip with a value line and a small caption (presets).
inline lv_obj_t *choice(lv_obj_t *p, int x, int y, int w, int h, const std::string &main, const std::string &sub,
                        uint32_t ic = 0) {
  lv_obj_t *b = box(p, x, y, w, h, C_SURF, 16);
  lv_obj_set_style_border_width(b, 2, 0);
  lv_obj_set_style_border_color(b, col(C_SURF), 0);
  pressable(b);
  int ty = sub.empty() ? (h - 24) / 2 : 8;
  if (ic) {
    lv_obj_t *i = icon(b, ic, F.i24, C_TEXT2);
    lv_obj_align(i, LV_ALIGN_TOP_MID, 0, 8);
    ty = 36;
  }
  const lv_font_t *mf = (ic || main.size() > 7) ? F.t16 : F.t20;  // long names get the smaller face
  if (!ic && sub.empty()) ty = (h - (int) lv_font_get_line_height(mf)) / 2;
  lv_obj_t *m = text(b, main, mf, C_TEXT, 0, ty, w - 8, LV_TEXT_ALIGN_CENTER);
  lv_obj_set_x(m, 4);
  if (!sub.empty()) {
    lv_obj_t *s = text(b, sub, F.t13, C_TEXT2, 4, ty + (ic ? 20 : 26), w - 8, LV_TEXT_ALIGN_CENTER);
    (void) s;
  }
  return b;
}
inline void choice_sel(lv_obj_t *b, bool sel) {
  lv_obj_set_style_border_color(b, col(sel ? C_ACCENT : C_SURF), 0);
  anim_color(b, sel ? C_ACCENT_BG : C_SURF);
}

